import fortis.host { Console }
func main(console: Console) {
let seed = Array[Int, 2].filled(0)
let arr: Array[Int, 3] = Array.filled(7)
console.print("${seed.count()} ${arr.count()}")
}

import fortis.host { Console }
func main(console: Console) {
let two = Array[Int, 2].filled
let three = Array[Int, 3].filled
let a = two(0)
let b = three(7)
console.print("${a.count()} ${b.count()}")
}

import fortis.host { Console }
func main(console: Console) {
let mut xs: List[Int] = List.of(1, 2)
xs[0] = 9
console.print("${xs.get(0) ?? 0}")
}

import fortis.host { Console }
func poke(s: editable { n: Int }) { s.n = 9 }
func main(console: Console) {
let mut s: { n: Int } = { n: 1 }
poke(editable s)
console.print("${s.n}")
}

import fortis.host { Console }
import fortis.text
func main(console: Console) {
console.print("${text.graphemes("aé")}")
}

import fortis.host { Console }
func widen(s: { n: Int<0..3>? }) { n: Int? } { return s }
func main(console: Console) {
let s: { n: Int<0..3>? } = { n: 1 }
let w = widen(s)
match w.n {
present(n) => console.print("${n}")
null => console.print("null")
}
}

import fortis.host { Console }
func make() Array[Int, 3] { return Array.filled(7) }
func size(a: Array[Int, 4]) Int { return a.count() }
func main(console: Console) {
let a = make()
console.print("${a.count()} ${size(Array.filled(5))}")
}

import fortis.host { Console }
func main(console: Console) {
let pair: (Int?, Int?) = (1, null)
console.print("${pair.0 ?? 0} ${pair.1 ?? 2}")
}

import fortis.host { Console }
class Box { export n: Int? }
func main(console: Console) {
let b = Box(n: 1)
console.print("${b.n ?? 0}")
}

import fortis.host { Console }
import fortis.text as words
func main(console: Console) {
console.print("${words.graphemes("aé")}")
}

import fortis.host { Console }
func main(console: Console) {
  let mut xs: List[Int<0..3>?] = List.of(1)
  xs[0] = 3
  console.print("${xs.get(0) ?? 0}")
  xs[0] = null
  console.print("${xs.get(0) ?? 0}")
  console.print("${xs.get(9) ?? 0}")
}

import fortis.host { Console }
func main(console: Console) {
  let xs: List[String?] = List.of(String.from("kept"))
  console.print("${xs.get(0) ?? "empty"}")
  console.print("${xs.get(9) ?? "empty"}")
  let a = Array[Int?, 2].filled(2)
  console.print("${a.get(0) ?? 0}")
}
